package main

import "fmt"

func fib(n int) int {
	if n < 2 {
		return n
	}
	a, b := 0, 1
	for i := 2; i <= n; i++ {
		a, b = b, a+b
	}
	return b
}

func main() {
	sum := 0
	for i := 0; i < 1500000; i++ {
		sum += (i * i) % 97
	}

	fibSum := 0
	for i := 0; i < 30; i++ {
		fibSum += fib(i)
	}

	fmt.Printf("sum=%d fibSum=%d\n", sum, fibSum)
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

func main() {
	var sb strings.Builder
	for i := 0; i < 90000; i++ {
		sb.WriteString(strconv.Itoa(i % 10))
	}

	var lines strings.Builder
	for i := 0; i < 20000; i++ {
		fmt.Fprintf(&lines, "item-%04d: value=%d ratio=%.3f\n", i, i*3, float64(i)/7.0)
	}

	fmt.Printf("strlen=%d lineslen=%d\n", sb.Len(), lines.Len())
}

package main

import (
	"fmt"
	"sort"
	"strconv"
)

func main() {
	counts := map[string]int{}
	for i := 0; i < 220000; i++ {
		key := strconv.Itoa(i % 60)
		counts[key]++
	}

	keys := make([]string, 0, len(counts))
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	total := 0
	for _, k := range keys {
		total += counts[k]
	}

	nums := make([]int, 0, 12000)
	for i := 0; i < 12000; i++ {
		nums = append(nums, (i*7919)%10007)
	}
	sort.Ints(nums)

	fmt.Printf("keys=%d maptotal=%d sorted_first=%d sorted_last=%d\n",
		len(keys), total, nums[0], nums[len(nums)-1])
}

